PRAGMA foreign_keys = ON;
CREATE TABLE provisioning (id INTEGER PRIMARY KEY CHECK(id=1), created_at TEXT NOT NULL);
CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL, password_hash TEXT NOT NULL, disabled INTEGER NOT NULL DEFAULT 0 CHECK(disabled IN(0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE workspaces (id TEXT PRIMARY KEY, name TEXT NOT NULL, retention_days INTEGER NOT NULL DEFAULT 365 CHECK(retention_days BETWEEN 1 AND 3650), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE workspace_members (workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id), role TEXT NOT NULL CHECK(role IN('Owner','Admin','Agent')), created_at TEXT NOT NULL, PRIMARY KEY(workspace_id,user_id));
CREATE TABLE sessions (id_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL, workspace_id TEXT NOT NULL, csrf_hash TEXT NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL, idle_expires_at TEXT NOT NULL, rotated_at TEXT NOT NULL, FOREIGN KEY(workspace_id,user_id) REFERENCES workspace_members(workspace_id,user_id) ON DELETE CASCADE);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE auth_limits (key_hash TEXT PRIMARY KEY, attempts INTEGER NOT NULL, reset_at TEXT NOT NULL);
CREATE TABLE audit_logs (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, actor_id TEXT REFERENCES users(id), action TEXT NOT NULL, target_id TEXT, created_at TEXT NOT NULL);
CREATE INDEX audit_workspace_time ON audit_logs(workspace_id,created_at DESC);
CREATE TABLE meta_connections (workspace_id TEXT PRIMARY KEY REFERENCES workspaces(id) ON DELETE CASCADE, meta_user_id TEXT NOT NULL, token_encrypted TEXT NOT NULL, token_expires_at TEXT, permissions_json TEXT NOT NULL, status TEXT NOT NULL, last_error TEXT, connected_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE oauth_states (state_hash TEXT PRIMARY KEY, session_hash TEXT NOT NULL REFERENCES sessions(id_hash) ON DELETE CASCADE ON UPDATE CASCADE, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, expires_at TEXT NOT NULL);
CREATE TABLE facebook_pages (workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, id TEXT NOT NULL, name TEXT NOT NULL, token_encrypted TEXT NOT NULL, token_expires_at TEXT, tasks_json TEXT NOT NULL, authorized INTEGER NOT NULL DEFAULT 0, subscribed INTEGER NOT NULL DEFAULT 0, last_sync_at TEXT, last_webhook_at TEXT, last_error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(workspace_id,id));
CREATE INDEX pages_external ON facebook_pages(id,authorized);
CREATE TABLE instant_forms (workspace_id TEXT NOT NULL, id TEXT NOT NULL, page_id TEXT NOT NULL, name TEXT NOT NULL, status TEXT NOT NULL, questions_json TEXT NOT NULL DEFAULT '[]', selected INTEGER NOT NULL DEFAULT 0 CHECK(selected IN(0,1)), last_sync_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(workspace_id,id), FOREIGN KEY(workspace_id,page_id) REFERENCES facebook_pages(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE leads (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, lead_id TEXT NOT NULL, form_id TEXT NOT NULL, page_id TEXT NOT NULL, name TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', campaign TEXT NOT NULL DEFAULT '', ad_id TEXT, submitted_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'New' CHECK(status IN('New','Contacted','Interested','Converted','Rejected')), assigned_to TEXT, field_data_json TEXT NOT NULL, source TEXT NOT NULL DEFAULT 'meta', source_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(workspace_id,page_id,lead_id), UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,assigned_to) REFERENCES workspace_members(workspace_id,user_id));
CREATE INDEX leads_workspace_submitted ON leads(workspace_id,submitted_at DESC,id);
CREATE INDEX leads_workspace_status ON leads(workspace_id,status,submitted_at DESC);
CREATE INDEX leads_workspace_form ON leads(workspace_id,form_id,submitted_at DESC);
CREATE INDEX leads_workspace_email ON leads(workspace_id,email);
CREATE INDEX leads_workspace_phone ON leads(workspace_id,phone);
CREATE INDEX leads_workspace_assignee ON leads(workspace_id,assigned_to,submitted_at DESC);
CREATE TABLE lead_answers (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, lead_id TEXT NOT NULL, field_key TEXT NOT NULL, question TEXT NOT NULL, values_json TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(workspace_id,lead_id,field_key), FOREIGN KEY(workspace_id,lead_id) REFERENCES leads(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE lead_notes (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, lead_id TEXT NOT NULL, author_id TEXT NOT NULL, body TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(workspace_id,lead_id) REFERENCES leads(workspace_id,id) ON DELETE CASCADE, FOREIGN KEY(workspace_id,author_id) REFERENCES workspace_members(workspace_id,user_id));
CREATE INDEX notes_lead_time ON lead_notes(workspace_id,lead_id,created_at);
CREATE TABLE lead_activities (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, lead_id TEXT NOT NULL, actor_id TEXT, kind TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(workspace_id,lead_id) REFERENCES leads(workspace_id,id) ON DELETE CASCADE, FOREIGN KEY(workspace_id,actor_id) REFERENCES workspace_members(workspace_id,user_id));
CREATE INDEX activities_lead_time ON lead_activities(workspace_id,lead_id,created_at);
CREATE TABLE tasks (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, lead_id TEXT, title TEXT NOT NULL, due_at TEXT NOT NULL, priority TEXT NOT NULL CHECK(priority IN('Low','Normal','High')), assigned_to TEXT, completed_at TEXT, created_by TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(workspace_id,lead_id) REFERENCES leads(workspace_id,id) ON DELETE CASCADE, FOREIGN KEY(workspace_id,assigned_to) REFERENCES workspace_members(workspace_id,user_id), FOREIGN KEY(workspace_id,created_by) REFERENCES workspace_members(workspace_id,user_id));
CREATE INDEX tasks_workspace_due ON tasks(workspace_id,completed_at,due_at);
